fn frame(t: i32) {
    host::display::clear(0x101014);
    if host::display::state_get(0) == 0 {
        host::display::state_set(1, host::net::open(0));
        host::display::state_set(0, 1);
    }
    let h: i32 = host::display::state_get(1);
    if t % 120 == 0 {
        let mut ok: i32 = 0;
        if h >= 0 && host::net::status(h) == 1 {
            ok = host::net::send(h, 4096);
        }
        if ok == 1 {
            host::display::state_set(2, host::display::state_get(2) + 1);
            host::display::state_set(4, 10);
        } else {
            host::display::state_set(3, host::display::state_get(3) + 1);
            host::display::state_set(5, 10);
        }
    }
    host::display::draw_string(100, 50, "HEARTBEAT SENDER", 0xffffff, 2);
    host::display::draw_string(80, 140, "SENT", 0x22bb44, 2);
    host::display::draw_number(80, 180, host::display::state_get(2), 0xffffff, 4);
    host::display::draw_string(300, 140, "FAILED", 0xbb3333, 2);
    host::display::draw_number(300, 180, host::display::state_get(3), 0xffffff, 4);
    let gflash: i32 = host::display::state_get(4);
    if gflash > 0 {
        host::display::fill_rect(80, 260, 120, 16, 0x22bb44);
        host::display::state_set(4, gflash - 1);
    }
    let rflash: i32 = host::display::state_get(5);
    if rflash > 0 {
        host::display::fill_rect(300, 260, 120, 16, 0xbb3333);
        host::display::state_set(5, rflash - 1);
    }
    let next: i32 = 120 - t % 120;
    host::display::draw_string(80, 330, "NEXT BEAT", 0x888888, 1);
    host::display::fill_rect(80, 350, next * 3, 8, 0x66ddff);
    host::display::present();
}
